:root {
  --bg: #1e1e2e;
  --card: #2a2a3a;
  --text: #e0e0e0;
  --accent: #f5c542;
  --accent-hover: #ffd966;
  --accent-pressed: #d4a82e;
  --secondary: #6b6b8b;
  --secondary-hover: #8a8aab;
  --secondary-pressed: #4e4e6b;
  --focus: #f5c542;
  --radius: 8px;
  --border: 4px solid #000;
  --shadow: 4px 4px 0 #000;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.meter {
  background: var(--card);
  border: var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  margin: 0;
  font-size: 1.6rem;
  text-align: center;
  letter-spacing: 1px;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.display {
  background: #0f0f1a;
  border: var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.display-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 1.3rem;
}

.label {
  color: var(--accent);
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.value {
  font-family: 'Courier New', monospace;
  font-weight: bold;
  font-size: 1.8rem;
  color: #fff;
  text-shadow: 2px 2px 0 #000;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

button {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: bold;
  padding: 12px 20px;
  border: var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
  background: var(--accent);
  color: #1e1e2e;
  flex: 1 1 auto;
  min-width: 100px;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  background: var(--accent-pressed);
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #000;
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button.secondary {
  background: var(--secondary);
  color: #fff;
}

button.secondary:hover {
  background: var(--secondary-hover);
}

button.secondary:active {
  background: var(--secondary-pressed);
}

.status {
  margin: 0;
  text-align: center;
  font-size: 0.95rem;
  color: #aaa;
  min-height: 1.5em;
}

@media (max-width: 400px) {
  .meter {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .value {
    font-size: 1.5rem;
  }
  button {
    font-size: 1rem;
    padding: 10px 14px;
    min-width: 80px;
  }
}

const MAX_MINUTES = 180;
const RATE_PER_HOUR = 2.00;

let totalMinutes = 0;

const timeEl = document.getElementById('time');
const priceEl = document.getElementById('price');
const statusEl = document.getElementById('status');
const add15Btn = document.getElementById('add15');
const add60Btn = document.getElementById('add60');
const clearBtn = document.getElementById('clear');

function formatTime(minutes) {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return `${h}:${m.toString().padStart(2, '0')}`;
}

function formatPrice(minutes) {
  const price = (minutes / 60) * RATE_PER_HOUR;
  return `$${price.toFixed(2)}`;
}

function updateDisplay() {
  timeEl.textContent = formatTime(totalMinutes);
  priceEl.textContent = formatPrice(totalMinutes);
  if (totalMinutes >= MAX_MINUTES) {
    statusEl.textContent = 'Maximum time reached (3 hours)';
  } else {
    statusEl.textContent = '';
  }
}

function addMinutes(minutes) {
  const newTotal = Math.min(totalMinutes + minutes, MAX_MINUTES);
  if (newTotal === totalMinutes) {
    statusEl.textContent = 'Maximum time reached (3 hours)';
    return;
  }
  totalMinutes = newTotal;
  updateDisplay();
}

function clearMeter() {
  totalMinutes = 0;
  updateDisplay();
  statusEl.textContent = 'Meter cleared';
}

add15Btn.addEventListener('click', () => addMinutes(15));
add60Btn.addEventListener('click', () => addMinutes(60));
clearBtn.addEventListener('click', clearMeter);

updateDisplay();
